import{_ as p,c as e,a2 as a,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第二百二十章 如何让内心清净","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/220第二百二十章 如何让内心清净.md","filePath":"meditation/巴利文大藏经/220第二百二十章 如何让内心清净.md"}'),r={name:"meditation/巴利文大藏经/220第二百二十章 如何让内心清净.md"};function _(n,t,i,s,d,c){return o(),e("div",null,t[0]||(t[0]=[a('<h1 id="第二百二十章-如何让内心清净" tabindex="-1">第二百二十章 如何让内心清净 <a class="header-anchor" href="#第二百二十章-如何让内心清净" aria-label="Permalink to &quot;第二百二十章 如何让内心清净&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部22相应5经/定经(蕴相应/蕴篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“比丘们（出家人）！你们要让内心保持宁静、安静，你们要让内心集中安住在清净的境界中而不要让内心散乱，不要让内心胡思乱想。让内心清净下来需要明白什么呢？需要明白物质事物，包括物质身体在内的起因与灭尽，需要明白感受的起因与灭尽，需要明白念想的起因与灭尽，需要明白行为的起因与灭尽，需要明白认识、分别、判断的起因与灭尽。</p><p>比丘们！什么是物质事物、物质身体的起因呢？什么是感受的起因呢？什么是念想的起因呢？什么是行为的起因呢？什么是认识、分别、判断的起因呢？</p><p>比丘们！喜欢、爱好、沉迷、贪恋物质事物、物质身体，就会执着不舍，凡是对物质事物、物质身体生起了欢喜，并执着不舍就是「取」，什么是「取」？就是执着、执取，对世间的事物事情产生了贪欲执着不舍、坚持不放；执着不合乎因果的错误见解；执着与解脱无关的禁戒与禁忌；执着世间有真实的我存在的论点，为了追求和获得这些贪恋执着的事物和思想而产生了身体行为，口说言语，内心念想的实际行为，这个就叫做「取」。</p><p>以「取」为前提条件就会产生「有」，什么是「有」？就是有了因缘果报的产生，做善事得善报，做恶事得恶报。如果是为了满足欲望产生了行为、言语、念想的实际行为，那么就会有欲望方面的因缘果报；如果是对世间的事物事情产生了行为、言语、念想的实际行为，那么就会有物质事物方面的因缘果报。如果是对精神思想方面产生了行为、言语、念想的实际行为，那么就会有精神思想方面的因缘果报，总之破坏、损害、伤害事物、众生，那么做出这些行为的人或众生就会同样受到破坏、损害、伤害的果报。弟子们有了因缘果报的产生就是「有」。</p><p>以「有」为前提条件就会产生「生」，什么是「生」？就是世间有了不同类别的众生产生，有了众生的出生、投胎、再次出生，以及有了世间事物、身体、感受、思想、行为、认识分别判断的显现和产生，有了各个容纳众生生存、生活地方的产生。弟子们这些就称为「生」。以「生」为前提条件就会产生忧愁、悲伤、苦闷、忧虑、绝望、衰老、死亡。弟子们这就是世间人痛苦和烦恼聚集的过程。</p><p>比丘们！同样的道理，喜欢、爱好、沉迷、贪恋感受、念想、行为、认识、分别、判断，就会执着不舍，凡是对感受、念想、行为、认识、分别、判断生起了欢喜，并执着不舍就是「取」。以「取」为前提条件就会产生「有」，以「有」为前提条件就会产生「生」，以「生」为前提条件就会产生忧愁、悲伤、苦闷、忧虑、绝望、衰老、死亡。比丘们，这就是世间人痛苦和烦恼聚集的过程。</p><p>比丘们！这就是物质事物、物质身体的起因，这就是感受、念想、行为、认识、分别、判断的起因。</p><p>比丘们！什么是物质事物、物质身体的灭尽？什么是感受、念想、行为、认识、分别、判断的灭尽呢？比丘们！不喜欢、不爱好、不沉迷、不贪恋物质事物、物质身体，就不会对物质事物、物质身体执着不舍。对物质事物、物质身体不生起欢喜，那么欢喜就会被灭尽，欢喜灭尽了，就不会对物质事物、物质身体执着不舍，「取」就灭尽了；「取」灭尽了，那么「有」就灭尽了；「有」灭尽了，「生」就灭尽了；「生」灭尽了，忧愁、悲伤、苦闷、忧虑、绝望、衰老、死亡就灭尽了。弟子们这就是世间人痛苦和烦恼灭尽的过程。”</p><p>比丘们！同样的道理，不喜欢、不爱好、不沉迷、不贪恋感受、念想、行为、认识、分别、判断，就不会对感受、念想、行为、认识、分别、判断执着不舍。对感受、念想、行为、认识、分别、判断不生起欢喜，那么欢喜就会被灭尽，欢喜灭尽了，就不会对感受、念想、行为、认识、分别、判断执着不舍，「取」就灭尽了；「取」灭尽了，那么「有」就灭尽了；「有」灭尽了，「生」就灭尽了；「生」灭尽了，忧愁、悲伤、苦闷、忧虑、绝望、衰老、死亡就灭尽了。弟子们这就是世间人痛苦和烦恼灭尽的过程。</p><p>比丘们！这就是物质事物、物质身体的灭尽，这就是感受、念想、行为、认识、分别、判断的灭尽。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',14)]))}const f=p(r,[["render",_]]);export{m as __pageData,f as default};
